/**
 * `--types`: a typed event map, generated from the code that already sends the events.
 *
 * `@micaforge/sdk`'s `track(name: string, props?: Props)` takes any name and any
 * properties; it is not generic, and a generic parameter on it would be a breaking
 * change to its published types for every caller. So the generated file is a thin typed
 * wrapper around it instead: an interface naming every event and its properties, and a
 * `track` with the same runtime behaviour that only accepts those. Import `track` from
 * the generated file instead of from the SDK, and a misspelled event or a property of the
 * wrong type stops compiling.
 *
 * How a property is typed: the union of the literal types seen for it across every call
 * site, `PropValue` when a call site passes a value the scanner cannot see; required
 * when every call site sends it, optional otherwise. An event that some call site sends
 * with properties the scanner cannot see (a spread, an object passed by name) also
 * accepts any other key.
 */
import type { EventSummary, PropType } from "./model.js";

/** The TypeScript type for a set of property types seen in the code. */
function tsType(types: PropType[]): string {
  if (types.includes("unknown")) return "PropValue";
  const map: Record<Exclude<PropType, "unknown">, string> = {
    string: "string",
    number: "number",
    boolean: "boolean",
    null: "null",
    array: "PropValue[]",
    object: "{ [key: string]: PropValue }",
  };
  return [...new Set(types.map((t) => map[t as Exclude<PropType, "unknown">]))].sort().join(" | ");
}

/** A property key, quoted when it is not a plain identifier. */
const key = (k: string) => (/^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k));

/** The generated module's text. */
export function generateTypes(events: EventSummary[], sdkModule = "@micaforge/sdk"): string {
  const body = events
    .filter((e) => e.name.trim())
    .map((event) => {
      const fields = event.props.map((p) => `    ${key(p.key)}${p.everywhere ? "" : "?"}: ${tsType(p.types)};`);
      if (event.propsDynamic) fields.push("    [key: string]: PropValue | undefined;");
      const shape = fields.length ? `{\n${fields.join("\n")}\n  }` : "Record<string, never>";
      const where = event.occurrences
        .slice(0, 3)
        .map((o) => `${o.file}:${o.line}`)
        .join(", ");
      const more = event.occurrences.length > 3 ? ` and ${event.occurrences.length - 3} more` : "";
      return `  /** Sent from ${where}${more}. */\n  ${JSON.stringify(event.name)}: ${shape};`;
    })
    .join("\n");

  return `// Generated by micaforge-scan from the events in this codebase. Do not edit by hand:
// run \`micaforge-scan --types <this file>\` again after adding or changing an event.
import { track as untypedTrack } from ${JSON.stringify(sdkModule)};
import type { PropValue, Props } from ${JSON.stringify(sdkModule)};

/** Every event the code sends, with the properties it sends with it. */
export interface MicaforgeEvents {
${body}
}

/** The name of an event this codebase sends. */
export type MicaforgeEventName = keyof MicaforgeEvents;

/** Properties are optional for an event that needs none, and required when some are. */
type PropsArgument<E extends MicaforgeEventName> = {} extends MicaforgeEvents[E]
  ? [props?: MicaforgeEvents[E]]
  : [props: MicaforgeEvents[E]];

/** Every event name, for a select box or a test. */
export const MICAFORGE_EVENTS = ${JSON.stringify(events.filter((e) => e.name.trim()).map((e) => e.name))} as const satisfies readonly MicaforgeEventName[];

/** \`track()\` from ${sdkModule}, accepting only the events above. */
export function track<E extends MicaforgeEventName>(name: E, ...args: PropsArgument<E>): void {
  untypedTrack(name, args[0] as Props | undefined);
}
`;
}
